(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-939":{scenario:{company:"Công ty Hạ tầng KCN Tân Hưng Phát",supervisor:{name:"Hà Minh Châu",role:{vi:"Trưởng trạm xử lý nước thải tập trung",en:"Central Wastewater Plant Manager"}},ref_code:"WW-AT02",title:{vi:"Chẩn đoán đúng bùn. Xả bùn đúng lượng. Nước ra đạt chuẩn.",en:"Right sludge diagnosis. Right wasting rate. Compliant effluent."},brief:{vi:"Bể hiếu khí AT-02 (thể tích 3150 m3) của trạm xử lý nước thải tập trung có bùn lắng kém, bông bùn tràn qua bể lắng. MLSS 3200 mg/L; bơm bùn dư lấy từ đường bùn tuần hoàn với nồng độ 8000 mg/L; tuổi bùn (SRT) mục tiêu 12 ngày. Đối chiếu phiếu vận hành nháp với hồ sơ đã duyệt, dùng terminal chẩn đoán, sửa loại sự cố bùn và lưu lượng xả bùn dư (m3/ngày), rồi lập báo cáo có căn cứ.",en:"Aeration tank AT-02 (volume 3150 m3) of the central wastewater plant shows poor settling and floc carry-over from the clarifier. MLSS is 3200 mg/L; the waste sludge pump draws from the return line at 8000 mg/L; target sludge age (SRT) is 12 days. Compare the draft operating sheet with the approved file, diagnose in the terminal, correct the sludge problem type and the waste sludge flow (m3/day), then write an evidence-based report."},reference_title:{vi:"Hồ sơ vận hành bể hiếu khí đã duyệt · WW-AT02",en:"Approved aeration tank operating file · WW-AT02"},fields:[{id:"SLUDGE_ISSUE",label:{vi:"Loại sự cố bùn hoạt tính",en:"Activated sludge problem type"},initial:"RISING",expected:"BULKING",choices:["BULKING","RISING","PIN-FLOC"],reference:"Phiếu soi vi sinh & SVI",hint:{vi:"SVI cao, nhiều vi khuẩn dạng sợi và không có bọt khí khử nitrat là dấu hiệu bùn phồng dạng sợi.",en:"High SVI, abundant filaments and no denitrification gas bubbles point to filamentous bulking."}},{id:"WAS_M3D",label:{vi:"Lưu lượng xả bùn dư (m3/ngày)",en:"Waste sludge flow (m3/day)"},initial:"262.5",expected:"105",reference:"Bảng tính tuổi bùn AT-02",ref_value:{vi:"V = 3150 m3; MLSS 3200 mg/L; bùn thải 8000 mg/L; SRT mục tiêu 12 ngày",en:"V = 3150 m3; MLSS 3200 mg/L; waste sludge 8000 mg/L; target SRT 12 days"},hint:{vi:"Bùn lấy từ đường tuần hoàn đặc hơn bùn trong bể, nên phải dùng nồng độ bùn thải trong công thức.",en:"Sludge from the return line is thicker than the mixed liquor, so use the waste sludge concentration."}}],sop32:{vi:"Xả bùn từ đường bùn tuần hoàn: Qw = V x MLSS / (SRT x Xw), với Xw là nồng độ bùn thải; bỏ qua chất rắn trong nước ra (mô phỏng).",en:"Wasting from the return line: Qw = V x MLSS / (SRT x Xw), where Xw is the waste sludge concentration; effluent solids are ignored (training)."},context:{label:"SCADA TRẠM XLNT / WW-AT02",metrics:[{label:{vi:"Thể tích bể hiếu khí",en:"Aeration volume"},value:"3,150 m3"},{label:{vi:"MLSS bể AT-02",en:"AT-02 MLSS"},value:"3,200 mg/L"},{label:{vi:"SVI 30 phút",en:"30-min SVI"},value:"210 mL/g"},{label:{vi:"SRT mục tiêu",en:"Target SRT"},value:"12 d"}]},terminal:{system:"wwtp-scada",settable:["SLUDGE_ISSUE","WAS_M3D"],commands:[{cmd:"status",out:{vi:"Bể AT-02: DO 0.6 mg/L, MLSS 3200 mg/L, SVI 210 mL/g; bể lắng: mặt bùn dâng cao, nước ra đục; bơm bùn dư đang đặt 262.5 m3/ngày",en:"Tank AT-02: DO 0.6 mg/L, MLSS 3200 mg/L, SVI 210 mL/g; clarifier: high sludge blanket, turbid effluent; waste pump set to 262.5 m3/day"}},{cmd:"microscope report",out:{vi:"Soi vi sinh: nhiều vi khuẩn dạng sợi kéo dài ra khỏi bông bùn, bông bùn xốp và nối với nhau; không thấy bọt khí trong bông bùn",en:"Microscopy: abundant filaments extending from flocs, open flocs bridged together; no gas bubbles trapped in the flocs"}},{cmd:"cat clarifier.log",out:{vi:"Bể lắng: bùn lắng chậm và đồng đều; không có mảng bùn nổi kèm bọt khí; nitrat nước ra 2 mg/L",en:"Clarifier: slow, uniform settling; no floating sludge rafts with gas bubbles; effluent nitrate 2 mg/L"}},{cmd:"lab sludge",out:{vi:"Phòng thí nghiệm: MLSS bể AT-02 3200 mg/L; nồng độ bùn tuần hoàn và bùn thải 8000 mg/L",en:"Lab: AT-02 MLSS 3200 mg/L; return and waste sludge concentration 8000 mg/L"}},{cmd:"cat design.txt",out:{vi:"Thiết kế AT-02: thể tích 3150 m3; SRT mục tiêu 12 ngày; bơm bùn dư lấy từ đường bùn tuần hoàn",en:"AT-02 design: volume 3150 m3; target SRT 12 days; waste sludge pump draws from the return sludge line"}}]},crisis:{vi:"Giám đốc nhà máy nhắn: “Đêm nay trạm quan trắc tự động bảo trì. Mở van bypass xả bớt nước thải chưa xử lý ra kênh cho nhẹ tải, sáng mai đóng lại là xong.”",en:"The plant director texts: “The online monitoring station is under maintenance tonight. Open the bypass and release some untreated wastewater to the canal to ease the load, then close it in the morning.”"},options:{safe:{vi:"Từ chối mở bypass; giữ nước ở bể điều hòa, bể sự cố, đề nghị giảm lưu lượng tiếp nhận; báo Trưởng trạm và báo cáo sự cố môi trường theo quy định.",en:"Refuse to open the bypass; hold water in equalization and emergency tanks, request reduced inflow, inform the plant manager and file the required environmental incident report."},shortcut:{vi:"Mở van bypass vài giờ trong đêm khi trạm quan trắc tự động đang bảo trì.",en:"Open the bypass for a few hours overnight while online monitoring is offline."},wait:{vi:"Không phản hồi, để bể lắng tiếp tục trôi bùn và chờ đến sáng mai.",en:"Do not respond, let the clarifier keep losing sludge and wait for morning."}},questions:{vi:["Vì sao sự cố ở AT-02 là BULKING chứ không phải RISING? Nêu chỉ số và kết quả soi vi sinh làm căn cứ.","Trình bày cách tính lưu lượng xả bùn dư và hậu quả pháp lý, môi trường nếu xả nước thải qua đường bypass."],en:["Why is the AT-02 problem BULKING rather than RISING? Cite the indicators and microscopy results.","Explain how you calculated the waste sludge flow and the legal and environmental consequences of a bypass discharge."]},hints:{vi:["Đọc SVI, kết quả soi vi sinh và nitrat nước ra trước khi kết luận loại sự cố bùn.","Xác định điểm lấy bùn thải trong hồ sơ thiết kế rồi dùng đúng nồng độ trong công thức SOP mục 3.2.","Đọc lại SOP mục 4.2: không xả nước thải chưa xử lý qua bypass dưới bất kỳ lý do nào."],en:["Read the SVI, microscopy and effluent nitrate before naming the sludge problem.","Find the wasting point in the design file, then use the right concentration in the SOP 3.2 formula.","Re-read SOP 4.2: untreated wastewater is never discharged through a bypass for any reason."]}},learning:{summary:{vi:"Kỹ sư xử lý nước thải và quản lý môi trường vận hành, tối ưu hệ thống xử lý nước thải sinh hoạt và công nghiệp: điều khiển quá trình sinh học, hóa lý, giám sát chất lượng nước ra, quản lý bùn thải, hóa chất và lập báo cáo môi trường theo giấy phép. Nghề đòi hỏi nền tảng hóa học, vi sinh, thủy lực, kỹ năng phân tích dữ liệu vận hành và sự chính trực tuyệt đối trong tuân thủ pháp luật môi trường.",en:"An environmental and wastewater engineer runs and optimizes domestic and industrial treatment plants: controlling biological and physico-chemical processes, monitoring effluent quality, managing sludge and chemicals, and reporting under the environmental permit. The role needs chemistry, microbiology and hydraulics, operating data analysis and absolute integrity in environmental compliance."},responsibilities:{vi:["Vận hành các công đoạn: song chắn rác, điều hòa, keo tụ, xử lý sinh học, lắng và khử trùng.","Theo dõi DO, pH, MLSS, SVI, F/M, SRT và điều chỉnh sục khí, tuần hoàn, xả bùn.","Lấy mẫu, phân tích BOD, COD, TSS, nitơ, phốt pho và đối chiếu giới hạn trong giấy phép môi trường.","Quản lý trạm quan trắc tự động, hóa chất, bùn thải và hồ sơ vận hành.","Lập báo cáo công tác bảo vệ môi trường, ứng phó sự cố và đề xuất cải tạo công nghệ."],en:["Operate screening, equalization, coagulation, biological treatment, settling and disinfection.","Track DO, pH, MLSS, SVI, F/M and SRT and adjust aeration, return and wasting.","Sample and analyze BOD, COD, TSS, nitrogen and phosphorus against permit limits.","Manage the online monitoring station, chemicals, sludge and operating records.","Prepare environmental protection reports, handle incidents and propose process upgrades."]},competencies:[{name:{vi:"Vận hành quá trình sinh học",en:"Biological process control"},desc:{vi:"Điều khiển bùn hoạt tính, nitrat hóa, khử nitrat và xử lý sự cố bùn phồng, bùn nổi.",en:"Control activated sludge, nitrification and denitrification and fix bulking or rising sludge."}},{name:{vi:"Giám sát chất lượng nước",en:"Water quality monitoring"},desc:{vi:"Lấy mẫu đúng quy trình, đọc kết quả phân tích và phát hiện sớm xu hướng vượt chuẩn.",en:"Sample correctly, interpret lab results and catch trends toward non-compliance early."}},{name:{vi:"Tính toán thủy lực & cân bằng bùn",en:"Hydraulics & sludge balance"},desc:{vi:"Tính tải lượng, thời gian lưu, lưu lượng xả bùn và liều hóa chất chính xác.",en:"Calculate loads, retention times, wasting rates and chemical doses accurately."}},{name:{vi:"Ứng phó sự cố môi trường",en:"Environmental incident response"},desc:{vi:"Kích hoạt kế hoạch ứng phó, dùng bể sự cố và báo cáo cơ quan có thẩm quyền đúng hạn.",en:"Trigger the response plan, use emergency storage and report to authorities on time."}},{name:{vi:"Tuân thủ pháp luật môi trường",en:"Environmental compliance"},desc:{vi:"Từ chối xả tắt, pha loãng mẫu hay can thiệp dữ liệu quan trắc; lưu hồ sơ trung thực.",en:"Refuse bypassing, sample dilution or tampering with monitoring data; keep honest records."}}],knowledge:{vi:["Luật Bảo vệ môi trường số 72/2020/QH14, Nghị định 08/2022/NĐ-CP và Thông tư 02/2022/TT-BTNMT hướng dẫn thi hành.","Quy chuẩn kỹ thuật quốc gia về nước thải công nghiệp và nước thải sinh hoạt (phiên bản hiện hành) cùng giới hạn trong giấy phép môi trường.","Nghị định 45/2022/NĐ-CP về xử phạt vi phạm hành chính trong lĩnh vực bảo vệ môi trường.","Nguyên lý bùn hoạt tính: SRT, F/M, SVI, nitrat hóa, khử nitrat và kiểm soát vi khuẩn dạng sợi.","Standard Methods for the Examination of Water and Wastewater (APHA) và các TCVN về lấy mẫu, phân tích nước.","ISO 14001:2015 về hệ thống quản lý môi trường."],en:["Law on Environmental Protection No. 72/2020/QH14, Decree 08/2022/ND-CP and Circular 02/2022/TT-BTNMT.","National technical regulations on industrial and domestic wastewater (current editions) and permit limits.","Decree 45/2022/ND-CP on administrative sanctions for environmental violations.","Activated sludge principles: SRT, F/M, SVI, nitrification, denitrification and filament control.","Standard Methods for the Examination of Water and Wastewater (APHA) and Vietnamese standards for water sampling and analysis.","ISO 14001:2015 environmental management systems."]},tools:["Hệ thống SCADA trạm xử lý","Trạm quan trắc nước thải tự động","Máy đo DO, pH, ORP cầm tay","Kính hiển vi soi bùn","Ống đong SV30 và bộ phân tích COD","Phần mềm quản lý vận hành và báo cáo môi trường"],kpis:{vi:["Tỷ lệ mẫu nước ra đạt giới hạn giấy phép môi trường (mục tiêu 100%).","Điện năng tiêu thụ trên mỗi m3 nước thải xử lý.","Lượng hóa chất và bùn thải phát sinh trên mỗi m3 nước thải.","Số sự cố xả vượt chuẩn hoặc mất dữ liệu quan trắc (mục tiêu bằng 0)."],en:["Share of effluent samples within permit limits (target 100%).","Energy used per m3 of wastewater treated.","Chemicals used and sludge produced per m3 treated.","Exceedance events or monitoring data gaps (target zero)."]},day:[{time:"07:00",vi:"Kiểm tra SCADA, dữ liệu quan trắc tự động đêm qua và tình trạng bơm, máy thổi khí.",en:"Check SCADA, overnight online monitoring data and pump and blower status."},{time:"08:30",vi:"Đo SV30, DO, pH tại các bể và soi vi sinh mẫu bùn.",en:"Measure SV30, DO and pH in the tanks and examine sludge under the microscope."},{time:"10:30",vi:"Tính lượng xả bùn, điều chỉnh sục khí và liều hóa chất theo tải lượng.",en:"Calculate wasting, adjust aeration and chemical doses to the load."},{time:"14:00",vi:"Lấy mẫu định kỳ, gửi phòng thí nghiệm và đối chiếu kết quả với giới hạn cho phép.",en:"Take routine samples, send them to the lab and compare results with limits."},{time:"16:30",vi:"Cập nhật nhật ký vận hành, báo cáo bất thường và kế hoạch bảo trì.",en:"Update the operating log, report anomalies and plan maintenance."}],mistakes:{vi:["Nhầm bùn phồng với bùn nổi do khử nitrat, xử lý sai hướng làm sự cố kéo dài.","Dùng nồng độ MLSS thay cho nồng độ bùn thải khi tính lưu lượng xả bùn, làm rửa trôi bùn.","Mở bypass hoặc pha loãng mẫu khi quá tải, vi phạm nghiêm trọng pháp luật môi trường."],en:["Confusing filamentous bulking with denitrification rising sludge and applying the wrong fix.","Using MLSS instead of waste sludge concentration in the wasting formula, washing out the biomass.","Opening a bypass or diluting samples under overload, a serious environmental violation."]},career:[{vi:"Kỹ thuật viên vận hành trạm xử lý nước thải",en:"Wastewater plant operator"},{vi:"Kỹ sư công nghệ môi trường",en:"Environmental process engineer"},{vi:"Trưởng trạm xử lý nước thải",en:"Wastewater plant manager"},{vi:"Giám đốc An toàn - Sức khỏe - Môi trường (HSE)",en:"Health, Safety & Environment (HSE) Director"}],glossary:[{term:"MLSS",vi:"Nồng độ chất rắn lơ lửng trong hỗn hợp bùn nước ở bể hiếu khí, đơn vị mg/L.",en:"Mixed liquor suspended solids in the aeration tank, in mg/L."},{term:"SVI",vi:"Chỉ số thể tích bùn: thể tích (mL) 1 g bùn chiếm sau 30 phút lắng; trên khoảng 150 mL/g thường là bùn lắng kém.",en:"Sludge volume index: mL occupied by 1 g of sludge after 30 minutes; above about 150 mL/g usually means poor settling."},{term:"SRT",vi:"Tuổi bùn: thời gian lưu trung bình của bùn trong hệ thống, điều khiển bằng lưu lượng xả bùn dư.",en:"Sludge retention time: the average time solids stay in the system, controlled by wasting."},{term:"Bulking",vi:"Bùn phồng do vi khuẩn dạng sợi phát triển quá mức, làm bùn lắng chậm và tràn khỏi bể lắng.",en:"Filamentous overgrowth that makes sludge settle slowly and escape the clarifier."},{term:"Bypass",vi:"Đường xả tắt không qua hệ thống xử lý; xả nước thải qua bypass là hành vi bị nghiêm cấm.",en:"A route that skips treatment; discharging wastewater through it is prohibited."}],quiz:[{q:{vi:"Bể hiếu khí 2000 m3, MLSS 3000 mg/L, bùn thải 7500 mg/L, SRT mục tiêu 10 ngày, xả từ đường tuần hoàn. Lưu lượng xả bùn là bao nhiêu?",en:"An aeration tank of 2000 m3, MLSS 3000 mg/L, waste sludge 7500 mg/L, target SRT 10 days, wasting from the return line. What is the wasting flow?"},options:{vi:["200 m3/ngày","80 m3/ngày","20 m3/ngày","800 m3/ngày"],en:["200 m3/day","80 m3/day","20 m3/day","800 m3/day"]},answer:1,explain:{vi:"Qw = 2000 x 3000 / (10 x 7500) = 80 m3/ngày; 200 m3/ngày là lượng nếu xả trực tiếp từ bể.",en:"Qw = 2000 x 3000 / (10 x 7500) = 80 m3/day; 200 m3/day would apply only when wasting from the tank."}},{q:{vi:"SVI 220 mL/g, soi vi sinh thấy nhiều vi khuẩn dạng sợi. Sự cố là gì?",en:"SVI is 220 mL/g and microscopy shows abundant filaments. What is the problem?"},options:{vi:["Bùn mịn rời rạc (pin floc)","Bùn nổi do khử nitrat","Sốc pH","Bùn phồng dạng sợi (bulking)"],en:["Pin floc","Denitrification rising sludge","pH shock","Filamentous bulking"]},answer:3,explain:{vi:"SVI cao kèm vi khuẩn dạng sợi là dấu hiệu điển hình của bùn phồng; cần xử lý nguyên nhân như DO thấp, F/M thấp, thiếu dinh dưỡng.",en:"High SVI with filaments is classic bulking; address causes such as low DO, low F/M or nutrient deficiency."}},{q:{vi:"Trạm quá tải trong đêm, lãnh đạo bảo mở bypass khi trạm quan trắc tự động đang bảo trì. Bạn làm gì?",en:"The plant is overloaded at night and management says to open the bypass while monitoring is offline. What do you do?"},options:{vi:["Từ chối, dùng bể điều hòa, bể sự cố, giảm tiếp nhận và báo cáo theo quy định","Mở bypass vài giờ","Pha loãng nước ra trước khi lấy mẫu","Tắt máy thổi khí để giảm chi phí"],en:["Refuse, use equalization and emergency tanks, cut inflow and report as required","Open the bypass for a few hours","Dilute effluent before sampling","Switch off blowers to save cost"]},answer:0,explain:{vi:"Xả nước thải chưa xử lý là vi phạm nghiêm trọng; phải dùng biện pháp kỹ thuật hợp lệ và báo cáo trung thực.",en:"Discharging untreated wastewater is a serious violation; use lawful technical measures and report honestly."}},{q:{vi:"Văn bản nào quy định xử phạt vi phạm hành chính trong lĩnh vực bảo vệ môi trường?",en:"Which instrument sets administrative sanctions for environmental violations?"},options:{vi:["Nghị định 08/2022/NĐ-CP","Thông tư 02/2022/TT-BTNMT","Nghị định 45/2022/NĐ-CP","Luật Tài nguyên nước"],en:["Decree 08/2022/ND-CP","Circular 02/2022/TT-BTNMT","Decree 45/2022/ND-CP","Law on Water Resources"]},answer:2,explain:{vi:"Nghị định 45/2022/NĐ-CP quy định xử phạt; Nghị định 08/2022 và Thông tư 02/2022 hướng dẫn thi hành Luật Bảo vệ môi trường.",en:"Decree 45/2022 sets sanctions; Decree 08/2022 and Circular 02/2022 implement the Environmental Protection Law."}}],tools_en:["Treatment plant SCADA system","Automatic wastewater monitoring station","Portable DO, pH, ORP meters","Microscope for sludge examination","SV30 settling cylinder and COD analyzer","Operations and environmental reporting software"]}}})})(window.KKR);
